import React from 'react';
import {AbsoluteFill} from 'remotion';
import {useS,T,en,DUR,Easing,interpolate,clamp,FONT} from './kit';
// FE 27-nov-12h "Malco": 2.5D (volumen Vol, 3 capas con parallax, giro leve, sombra en el suelo, manos con volumen).
// VISUAL DE PAZ: camara que respira, fundidos de luz entre planos, polvo de luz; todo atado a las palabras de la voz.
export const SUBS={arriba:200,size:80,acento:'#FFD84D'};
export const SFX:{t:number;s:string}[]=[];
type Tri=[string,string,string];
type A4=[number,number,number,number];
const ts=(i:number)=>Math.max(0,T(i)-.2);
const q=(s:number,a:number,b:number)=>interpolate(s,[a,Math.max(a+.01,b)],[0,1],{...clamp,easing:Easing.inOut(Easing.cubic)});
const win=(s:number,a:number,b:number,f=.4)=>q(s,a,a+f)*(1-q(s,b,b+f));
const kf=(s:number,k:[number,number[]][]):number[]=>{if(s<=k[0][0])return k[0][1];for(let i=0;i<k.length-1;i++)if(s<k[i+1][0]){const u=q(s,k[i][0],k[i+1][0]);return k[i][1].map((v,j)=>v+(k[i+1][1][j]-v)*u);}return k[k.length-1][1];};
const ell=(cx:number,cy:number,rx:number,ry:number)=>`M${cx-rx} ${cy}a${rx} ${ry} 0 1 0 ${2*rx} 0a${rx} ${ry} 0 1 0 ${-2*rx} 0Z`;
// Capsula cerrada de (x1,y1) a (x2,y2) con grosor w: dedos, brazos y cuellos con volumen (no trazos sueltos).
const caps=(x1:number,y1:number,x2:number,y2:number,w:number)=>{const a=Math.atan2(y2-y1,x2-x1),r=w/2,nx=-Math.sin(a)*r,ny=Math.cos(a)*r;
 return `M${x1+nx} ${y1+ny}L${x2+nx} ${y2+ny}A${r} ${r} 0 0 0 ${x2-nx} ${y2-ny}L${x1-nx} ${y1-ny}A${r} ${r} 0 0 0 ${x1+nx} ${y1+ny}Z`;};
const P:Record<string,Tri>={
 skinP:['#ffdab4','#e5935e','#84402a'],skinM:['#f2b98a','#bb7344','#5e2c16'],skinL:['#ffdcb8','#e89c6a','#84432c'],skinJ:['#ffe2c4','#e8a272','#8c4c2c'],skinS:['#fbd0a8','#d38a5e','#6e3822'],
 robeP:['#e8a66e','#a2502a','#46200c'],robeM:['#e6eefb','#93a6cf','#38497a'],robeL:['#aef7b6','#31bd6a','#0e5e34'],robeJ:['#ffffff','#eaf0ff','#8d9bd8'],robeS:['#fff0b8','#5a72f0','#14226e'],
 manto:['#94c6ff','#3068ea','#0e2c90'],metal:['#f6fcff','#93b4d6','#2c4064'],cloak:['#ffa090','#dc2c34','#6c0c1a'],leather:['#ecaa78','#9c5434','#4a2412'],gold:['#fff6b8','#ffc63e','#a86a0c'],
 wood:['#dcaa78','#8e5a34','#3c1e12'],grayH:['#ffffff','#d2d8e6','#737b94'],blackH:['#7474a0','#2c2c48','#0c0c1c'],brownH:['#c08a66','#6e402a','#2c140a'],papel:['#fffce6','#f0dc9e','#aa8c52'],
 sash:['#ffd08a','#cc8034','#5e3410'],trunk:['#e8a88e','#8e5654','#3e1c3c'],trunkD:['#8a66a0','#432f6a','#170f36'],leafL:['#a6f5d0','#30bc9c','#0c4e60'],leafD:['#2f98b0','#10507e','#061a3e'],
 hill:['#4262e0','#1c2c98','#0a1252'],moon:['#ffffff','#eaf2ff','#a0b8e8'],glassR:['#ffe0ea','#ff6e9c','#8c1c4c'],glassC:['#d8fbff','#38d0f0','#0a6a88'],glassG:['#e4ffd8','#58e070','#1a7a30'],
 glassA:['#fff4c8','#ffb838','#9a5a08'],terra:['#f2a070','#c8603a','#6a2a14'],leafF:['#d8ffb0','#58d070','#146a3a'],stone:['#c8b4e8','#7a68c0','#2c2468'],
};
// Volumen: color medio, sombra suave abajo-derecha, luz suave arriba-izquierda y borde fino.
const Vol:React.FC<{id:string;d:string;c:Tri;sw?:number;o?:number;borde?:string}>=({id,d,c,sw=70,o=24,borde})=><g>
 <defs><clipPath id={id}><path d={d}/></clipPath></defs>
 <path d={d} fill={c[1]}/>
 <g clipPath={`url(#${id})`}>
  <path d={d} fill='none' stroke={c[2]} strokeWidth={sw} filter='url(#b18)' transform={`translate(${-o} ${-o})`}/>
  <path d={d} fill='none' stroke={c[0]} strokeWidth={sw*.75} filter='url(#b18)' transform={`translate(${o} ${o})`}/>
 </g>
 <path d={d} fill='none' stroke={borde||c[2]} strokeWidth={3} opacity={.55}/>
</g>;
// Volumen barato (degradado luz arriba-izquierda a sombra abajo-derecha) para piezas chicas o repetidas.
const Lite:React.FC<{d:string;c:string;sw?:number;o?:number}>=({d,c,sw=2,o=1})=><path d={d} fill={`url(#L${c})`} stroke={P[c][2]} strokeWidth={sw} strokeOpacity={.55} opacity={o}/>;
const Brillo2:React.FC<{x:number;y:number;rx:number;ry:number;r?:number;o?:number}>=({x,y,rx,ry,r=-30,o=.75})=><ellipse cx={x} cy={y} rx={rx} ry={ry} transform={`rotate(${r} ${x} ${y})`} fill='#fff' opacity={o} filter='url(#b6)'/>;
const Defs:React.FC=()=><defs>
 <filter id='b6' x='-50%' y='-50%' width='200%' height='200%'><feGaussianBlur stdDeviation='6'/></filter>
 <filter id='b18' x='-50%' y='-50%' width='200%' height='200%'><feGaussianBlur stdDeviation='18'/></filter>
 <filter id='b40' x='-50%' y='-50%' width='200%' height='200%'><feGaussianBlur stdDeviation='40'/></filter>
 {Object.entries(P).map(([k,c])=><linearGradient key={k} id={'L'+k} x1='0' y1='0' x2='1' y2='1'><stop stopColor={c[0]}/><stop offset='.5' stopColor={c[1]}/><stop offset='1' stopColor={c[2]}/></linearGradient>)}
 <radialGradient id='lamp'><stop stopColor='#ffc04a' stopOpacity='.8'/><stop offset='.35' stopColor='#ff8a1e' stopOpacity='.32'/><stop offset='1' stopColor='#ff7a00' stopOpacity='0'/></radialGradient>
 <radialGradient id='oro'><stop stopColor='#fff6b0' stopOpacity='.95'/><stop offset='.4' stopColor='#ffd23a' stopOpacity='.5'/><stop offset='1' stopColor='#ffc000' stopOpacity='0'/></radialGradient>
 <radialGradient id='sombra'><stop stopColor='#000' stopOpacity='.55'/><stop offset='1' stopColor='#000' stopOpacity='0'/></radialGradient>
 <radialGradient id='humo'><stop stopColor='#b0c0e8' stopOpacity='.6'/><stop offset='1' stopColor='#b0c0e8' stopOpacity='0'/></radialGradient>
 <radialGradient id='dot'><stop stopColor='#fff' stopOpacity='1'/><stop offset='.35' stopColor='#cfe4ff' stopOpacity='.55'/><stop offset='1' stopColor='#9ec8ff' stopOpacity='0'/></radialGradient>
 <linearGradient id='ray' x1='0' y1='0' x2='0' y2='1'><stop stopColor='#fff' stopOpacity='.55'/><stop offset='1' stopColor='#fff' stopOpacity='0'/></linearGradient>
 <linearGradient id='gnd' x1='0' y1='0' x2='0' y2='1'><stop stopColor='#2ec59a'/><stop offset='.35' stopColor='#0d6a6c'/><stop offset='1' stopColor='#041e30'/></linearGradient>
 <linearGradient id='gndD' x1='0' y1='0' x2='0' y2='1'><stop stopColor='#b8f59a'/><stop offset='.4' stopColor='#3aa86e'/><stop offset='1' stopColor='#0f4a40'/></linearGradient>
 <linearGradient id='wall' x1='0' y1='0' x2='0' y2='1'><stop stopColor='#ffb04a'/><stop offset='.5' stopColor='#c8602a'/><stop offset='1' stopColor='#4a1a10'/></linearGradient>
 <linearGradient id='noche' x1='0' y1='0' x2='0' y2='1'><stop stopColor='#1a2a9a'/><stop offset='1' stopColor='#5a3cd8'/></linearGradient>
 <radialGradient id='vin' cx='.5' cy='.5' r='.75'><stop offset='.62' stopColor='#000' stopOpacity='0'/><stop offset='1' stopColor='#000' stopOpacity='.42'/></radialGradient>
</defs>;
// ---------- piezas ----------
// Mano con volumen: palma Vol, dedos cerrados con luz y sombra, nudillos y unas. Muneca en (0,0), dedos hacia -y.
const Hand:React.FC<{id:string;ck:string;fist?:boolean;sp?:number;mir?:boolean;behind?:React.ReactNode;k?:number}>=({id,ck,fist=false,sp=.5,mir=false,behind,k=1})=>{
 const c=P[ck];const F:[number,number][]=[[-30,50],[-10,62],[10,58],[28,44]];
 return <g transform={`scale(${mir?-k:k} ${k})`}>{behind}
 {fist?<>
  <Vol id={id+'p'} d='M-38 0C-44 -30 -44 -62 -38 -94H38C44 -62 44 -30 38 0Q0 12 -38 0Z' c={c} sw={30} o={8}/>
  {[0,1,2,3].map(j=><Lite key={j} d={caps(-36+(j%2)*3,-78+j*21,36,-78+j*21,22)} c={ck} sw={2.5}/>)}
  <Lite d={caps(34,-34,-8,-92,23)} c={ck} sw={2.5}/>
  {[0,1,2,3].map(j=><ellipse key={j} cx={-22+(j%2)*3} cy={-84+j*21} rx={12} ry={3.5} fill='#fff' opacity='.4'/>)}
 </>:<>
  {F.map(([kx,L],j)=>{const a=(j-1.5)*sp*.17,tx=kx+Math.sin(a)*L,ty=-84-Math.cos(a)*L;return <g key={j}><Lite d={caps(kx,-84,tx,ty,j===3?17:20)} c={ck} sw={2.5}/><ellipse cx={tx} cy={ty+9} rx={5.5} ry={7.5} fill='#fff4ee' opacity='.7' stroke={c[2]} strokeWidth={1.5} strokeOpacity={.5}/></g>;})}
  <Vol id={id+'p'} d='M-38 0C-44 -26 -42 -60 -36 -90H36C44 -60 44 -26 38 0Q0 12 -38 0Z' c={c} sw={30} o={8}/>
  {[-30,-10,10,28].map((kx,j)=><ellipse key={j} cx={kx} cy={-84} rx={8} ry={5} fill={c[2]} opacity='.28'/>)}
  <Lite d={caps(-34,-22,-72,-62,25)} c={ck} sw={2.5}/><ellipse cx={-72} cy={-62} rx={6.5} ry={8} fill='#fff4ee' opacity='.7' stroke={c[2]} strokeWidth={1.5} strokeOpacity={.5}/>
 </>}
 </g>;};
const Arm:React.FC<{id:string;S:[number,number];e:[number,number];w:[number,number];sleeve:string;skin:string;fist?:boolean;sp?:number;mir?:boolean;behind?:React.ReactNode;wd?:number;hk?:number}>=({id,S,e,w,sleeve,skin,fist,sp,mir,behind,wd=62,hk=1})=>{
 const ang=Math.atan2(w[0]-e[0],-(w[1]-e[1]))*180/Math.PI;
 return <g>
  <Vol id={id+'u'} d={caps(S[0],S[1],e[0],e[1],wd)} c={P[sleeve]} sw={36} o={10}/>
  <Vol id={id+'l'} d={caps(e[0],e[1],w[0],w[1],wd-8)} c={P[sleeve]} sw={32} o={9}/>
  <g transform={`translate(${w[0]} ${w[1]}) rotate(${ang})`}><rect x={-30} y={-10} width={60} height={20} rx={9} fill={P[sleeve][2]} opacity='.4'/><Hand id={id+'h'} ck={skin} fist={fist} sp={sp} mir={mir} behind={behind} k={hk}/></g>
 </g>;};
const Sword:React.FC<{gl?:number}>=({gl=0})=><g>
 <Lite d={caps(0,12,0,-100,19)} c='leather'/>{[0,1,2,3,4].map(j=><path key={j} d={`M-9 ${-10-j*18}H9`} stroke='#4a2412' strokeWidth={3} opacity='.6'/>)}
 <ellipse cy={16} rx={20} ry={14} fill='url(#Lgold)'/><Lite d='M-52 -100H52L46 -116H-46Z' c='gold' sw={2.5}/>
 <Lite d='M-18 -116L-15 -390L0 -432L15 -390L18 -116Z' c='metal' sw={2.5}/>
 <path d='M-3 -122L-2 -392L2 -392L3 -122Z' fill='#fff' opacity='.75'/><path d='M0 -122V-405' stroke='#5a78a0' strokeWidth={2} opacity='.6'/>
 {gl>0&&<ellipse cy={-300} rx={40} ry={200} fill='#fff' opacity={gl*.55} filter='url(#b18)'/>}
</g>;
const HEAD='M0 -604C42 -604 64 -568 62 -522C60 -472 34 -440 0 -438C-34 -440 -60 -472 -62 -522C-64 -568 -42 -604 0 -604Z';
const ROBE='M-62 -446C-110 -440 -130 -385 -136 -300L-172 -8Q0 30 172 -8L136 -300C130 -385 110 -440 62 -446L0 -420Z';
const HAIRS='M-66 -516C-76 -600 -30 -624 0 -624C34 -624 78 -598 66 -516C60 -552 42 -574 0 -574C-42 -574 -60 -552 -66 -516Z';
const HAIRB='M0 -614C66 -614 84 -548 78 -480C76 -440 86 -408 76 -366C40 -344 -40 -344 -76 -366C-86 -408 -76 -440 -78 -480C-84 -548 -66 -614 0 -614Z';
const BEARD='M-60 -506C-72 -450 -44 -402 0 -396C44 -402 72 -450 60 -506C50 -482 34 -470 18 -470Q0 -456 -18 -470C-34 -470 -50 -482 -60 -506Z';
const REST_L:A4=[-125,-300,-135,-195],REST_R:A4=[125,-300,135,-195];
type PP={id:string;x:number;y:number;k?:number;flip?:boolean;s:number;skin:string;robe:string;hair:string;beard?:string;bs?:number;curly?:boolean;back?:boolean;head?:number;fr?:number;look?:number;lookY?:number;mouth?:number;fat?:number;L?:A4;R?:A4;fistL?:boolean;fistR?:boolean;behindR?:React.ReactNode;behindL?:React.ReactNode;sash?:string;rope?:boolean;extra?:React.ReactNode;under?:React.ReactNode;over?:React.ReactNode;sp?:number;tilt?:number};
// Persona 2.5D: cabeza con orejas, ojos con iris y parpado, nariz con fosas, labios, cuello, tunica con volumen, brazos y manos con volumen, sombra en el suelo.
const Person:React.FC<PP>=({id,x,y,k=1,flip=false,s,skin,robe,hair,beard,bs=1,curly=false,back=false,head=0,fr=0,look=0,lookY=0,mouth=0,fat=1,L=REST_L,R=REST_R,fistL,fistR,behindR,behindL,sash='sash',rope=false,extra,under,over,sp=.5,tilt=0})=>{
 const bob=Math.sin(s*1.3+x*.01)*3,sk=P[skin],hc=P[hair],sh=80*fat;
 return <g transform={`translate(${x} ${y+bob}) scale(${flip?-k:k} ${k}) rotate(${tilt})`}>
  <ellipse cy={16} rx={200*fat} ry={36} fill='#000' opacity='.42' filter='url(#b18)'/>
  {under}
  <g transform={`scale(${fat} 1)`}>
   <Lite d={ell(-62,8,38,15)} c={skin}/><Lite d={ell(62,8,38,15)} c={skin}/>
   <Vol id={id+'r'} d={ROBE} c={P[robe]} sw={84} o={26}/>
   <path d='M-60 -230C-70 -150 -90 -70 -104 -12M24 -230C32 -150 44 -70 54 -10M96 -220C104 -150 116 -70 134 -12' stroke={P[robe][2]} strokeWidth={9} fill='none' opacity='.22' filter='url(#b6)'/>
   <Lite d='M-142 -272C-60 -250 60 -250 142 -272L148 -228C60 -206 -60 -206 -148 -228Z' c={sash}/>
   {rope&&[0,1,2,3,4,5,6,7].map(j=><path key={j} d={`M${-130+j*38} ${-262+Math.abs(j-3.5)*-1} l12 30`} stroke='#7a4a1a' strokeWidth={5} opacity='.7'/>)}
   <path d='M-32 -448L0 -400L32 -448Z' fill={sk[1]}/>
  </g>
  {over}
  <Vol id={id+'n'} d={caps(0,-478,0,-430,52)} c={sk} sw={24} o={8}/>
  <g transform={`rotate(${head} 0 -440)`}>
   {back?<>
    {[-1,1].map(m=><Lite key={m} d={ell(m*64,-516,10,20)} c={skin}/>)}
    <Vol id={id+'hb'} d={HAIRB} c={hc} sw={50} o={14}/>
    <path d='M0 -610C4 -560 -6 -480 0 -380' stroke={hc[2]} strokeWidth={5} fill='none' opacity='.5'/>
    <Brillo2 x={-26} y={-570} rx={22} ry={40} r={20} o={.4}/>
   </>:<>
    {[-1,1].map(m=><g key={m}><Lite d={ell(m*63,-518,12,23)} c={skin}/><ellipse cx={m*63} cy={-518} rx={5} ry={12} fill={sk[2]} opacity='.35'/></g>)}
    <Vol id={id+'hd'} d={HEAD} c={sk} sw={70} o={22}/>
    {[-1,1].map(m=><ellipse key={m} cx={m*38} cy={-488} rx={20} ry={11} fill='#ff6a6a' opacity='.22' filter='url(#b6)'/>)}
    {beard&&<g transform={`translate(0 -506) scale(1 ${bs}) translate(0 506)`}><Vol id={id+'bd'} d={BEARD} c={P[beard]} sw={46} o={12}/>{curly&&[0,1,2,3,4,5,6,7].map(j=>{const a=(.1+j/7*.8)*Math.PI;return <circle key={j} cx={Math.cos(a)*-56} cy={-410-Math.sin(a)*-6+(Math.abs(j-3.5)*-5)} r={13} fill={`url(#L${beard})`} stroke={P[beard][2]} strokeWidth={1.5} strokeOpacity={.4}/>;})}</g>}
    <Vol id={id+'hr'} d={HAIRS} c={hc} sw={36} o={11}/>
    {curly&&[0,1,2,3,4,5,6,7,8].map(j=>{const a=Math.PI*(1.06+j*.108);return <circle key={j} cx={Math.cos(a)*68} cy={-516+Math.sin(a)*100} r={17} fill={`url(#L${hair})`} stroke={hc[2]} strokeWidth={1.5} strokeOpacity={.4}/>;})}
    <Lite d='M-4 -538C-8 -516 -17 -502 -15 -494C-9 -487 -3 -490 0 -487C3 -490 9 -487 15 -494C17 -502 8 -516 4 -538Z' c={skin}/>
    {[-1,1].map(m=><ellipse key={m} cx={m*8} cy={-492} rx={4.5} ry={2.8} fill='#4a1e10' opacity='.7'/>)}
    {[-1,1].map(m=><g key={m} transform={`translate(${m*26} ${-526-fr*3})`}>
     <g transform={`scale(${1+fr*.28})`}>
      <path d='M-17 0Q0 -13 17 0Q0 12 -17 0Z' fill='#fff' stroke='#2a160c' strokeWidth={1.5}/>
      <circle cx={look*4} cy={lookY*3} r={7.5} fill='#6a3a18'/><circle cx={look*4} cy={lookY*3} r={4} fill='#0a0a0a'/><circle cx={look*4+2.6} cy={lookY*3-2.8} r={2.4} fill='#fff'/>
      <path d='M-18 0Q0 -14 18 0' stroke='#2a160c' strokeWidth={3} fill='none'/>
     </g>
     <g transform={`translate(0 ${-fr*7}) scale(${m} 1)`}><path d='M-22 -22Q0 -32 22 -24L22 -18Q0 -26 -22 -15Z' fill={hc[2]}/></g>
    </g>)}
    {mouth>0&&<ellipse cx={0} cy={-462+mouth*6} rx={11} ry={mouth*13} fill='#3a0a10'/>}
    <path d='M-18 -466Q-9 -473 0 -469Q9 -473 18 -466Q0 -460 -18 -466Z' fill='#b8484a'/>
    <path d={`M-17 -466Q0 ${-457+mouth*16} 17 -466Q0 ${-448+mouth*24} -17 -466Z`} fill='#d8666a'/>
   </>}
  </g>
  <Arm id={id+'aL'} S={[-sh,-436]} e={[L[0],L[1]]} w={[L[2],L[3]]} sleeve={robe} skin={skin} fist={fistL} sp={sp} mir behind={behindL}/>
  <Arm id={id+'aR'} S={[sh,-436]} e={[R[0],R[1]]} w={[R[2],R[3]]} sleeve={robe} skin={skin} fist={fistR} sp={sp} behind={behindR}/>
  {extra}
 </g>;};
// ---------- ambiente ----------
const Torch:React.FC<{x:number;y:number;k?:number;s:number;len?:number;g?:number}>=({x,y,k=1,s,len=170,g=1})=>{
 const f=Math.sin(s*9+x)*.5+Math.sin(s*13+x*.3)*.5;
 return <g transform={`translate(${x} ${y}) scale(${k})`}>
  <ellipse cy={-90} rx={300} ry={340} fill='url(#lamp)' opacity={.85*g*(1+f*.06)}/>
  <Lite d={caps(0,0,0,len,15)} c='wood'/><Lite d='M-20 -6L-14 -48L14 -48L20 -6Z' c='leather'/>
  <g transform={`scale(${1+f*.05} ${1+f*.12}) skewX(${f*4})`}>
   <path d='M0 -40C-46 -66 -50 -120 -16 -170C-14 -140 6 -132 12 -158C52 -118 40 -64 0 -40Z' fill='#ff7a18'/>
   <path d='M0 -44C-28 -62 -30 -102 -8 -136C-4 -116 10 -108 14 -128C36 -98 26 -62 0 -44Z' fill='#ffc233'/>
   <path d='M0 -48C-12 -60 -12 -84 0 -104C14 -84 12 -60 0 -48Z' fill='#fff6c0'/>
  </g>
  {[0,1,2].map(j=>{const u=((s*.5+j/3)%1);return <circle key={j} cx={Math.sin(s*2+j*2)*16+u*14} cy={-150-u*200} r={14+u*26} fill='url(#humo)' opacity={(1-u)*.55}/>;})}
 </g>;};
const Tree:React.FC<{id:string;x:number;y:number;k?:number;flip?:boolean;s:number;far?:boolean}>=({id,x,y,k=1,flip=false,s,far=false})=>{
 const tk=far?'trunkD':'trunk',lk=far?'leafD':'leafL';
 return <g transform={`translate(${x} ${y}) scale(${flip?-k:k} ${k})`}>
  <ellipse cy={10} rx={130} ry={22} fill='url(#sombra)'/>
  {far?<Lite d='M-58 0C-92 -110 -38 -210 -62 -310C-82 -400 -46 -470 -24 -540L30 -540C18 -470 62 -410 42 -320C22 -220 88 -110 60 0Q0 18 -58 0Z' c={tk}/>:<Vol id={id+'t'} d='M-58 0C-92 -110 -38 -210 -62 -310C-82 -400 -46 -470 -24 -540L30 -540C18 -470 62 -410 42 -320C22 -220 88 -110 60 0Q0 18 -58 0Z' c={P[tk]} sw={60} o={18}/>}
