const Bokeh:React.FC<{s:number;i:number;cerca?:boolean;col:string}>=({s,i,cerca=false,col})=><g>{Array.from({length:cerca?6:14}).map((_,j)=>{const r=cerca?60+((j*37+i*11)%70):18+((j*29+i*7)%40);const x=((j*263+i*97)%1300)-110,y=((j*389+i*151)%2100)-90;return <circle key={j} cx={x+Math.sin(s*.6+j)*30} cy={y+Math.cos(s*.5+j)*30} r={r} fill={cerca?'#fff4dc':col} opacity={cerca?.16:.32} filter={cerca?'url(#b18)':'url(#b6)'}/>;})}</g>;
const Scene:React.FC=()=>{
 const{s}=useS();let i=0;for(let j=1;j<SC.length;j++)if(s>=SC[j].t)i=j;
